        while d * d <= num:
            while num % d == 0:
                factors.add(d)
                num //= d
            d += 1
        if num > 1:
            factors.add(num)
        return factors

    def calculate_cost(prime):
        cost = 0
        current_sum = 0
        prefix_mods = []
        for x in a:
            current_sum += x
            prefix_mods.append(current_sum % prime)

        for p_mod in prefix_mods[:-1]:
            cost += min(p_mod, prime - p_mod)
        return cost

    prime_factors = get_prime_factors(total)
    min_cost = float('inf')

    for p in prime_factors:
        cost = calculate_cost(p)
        if cost < min_cost:
            min_cost = cost

    return str(min_cost)
