def min_tree_size(a):
    n = len(a)
    if n == 0:
        return 0
    a = sorted(a)

    @lru_cache(maxsize=None)
    def dp(mask):
        if mask == 0:
            return 0
        min_v = len(set(a))
        for i in range(n):
            if mask & (1 << i):
                remain = mask ^ (1 << i)
                curr = a[i]
                for j in range(i + 1, n):
