def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for line in lines[1:m+1]:
        u, v = map(int, line.split())
        edges.append((u, v))

    if n <= 1:
        return '0\n'

    adj = {i: [] for i in range(1, n + 1)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    components = []

    def dfs(start):
        stack = [start]
        component = []
        while stack:
            v = stack.pop()
            if visited[v]:
                continue
            visited[v] = True
            component.append(v)
            for neighbor in adj[v]:
                if not visited[neighbor]:
                    stack.append(neighbor)
        return component

    for i in range(1, n + 1):
        if not visited[i]:
            components.append(dfs(i))

    num_components = len(components)

    if num_components == 1:
        edges_in_tree = 0
        for v in components[0]:
            edges_in_tree += len(adj[v])
        edges_in_tree //= 2
        # For a tree, num_edges = num_vertices - 1
        needed_ops = max(0, edges_in_tree - (len(components[0]) - 1))
        return str(needed_ops) + '\n'
    else:
        needed_ops = num_components - 1
        # For cycles within components
        for comp in components:
            edges_in_comp = sum(len(adj[v]) for v in comp) // 2
            needed_ops += max(0, edges_in_comp - (len(comp) - 1))
        return str(needed_ops) + '\n'
