    inv[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, 0, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % MOD

    def combinations(n, k):
        if k < 0 or k > n:
            return 0
        return (fact[n] * inv[k] % MOD) * inv[n - k] % MOD

    from math import gcd, isqrt

