    n = len(s)
    best_i, best_len = -1, 0
    best_parts = None

    for start in range(1, n + 1):
        remaining = n - start + 1
        if remaining < 1:
            continue

        # Try each possible middle length (must be odd)
        for mid_len in range(1, remaining, 2):
            if mid_len > remaining:
                break

            middle = s[start - 1 + mid_len:]

            # Check if middle is a palindrome
            if middle != middle[::-1]:
                continue

            # Remaining characters after middle
            remaining_after = len(middle)
            prefix_part = s[start - 1]

            if remaining_after == 1:
                if prefix_part == middle:
                    if best_len < remaining:
                        best_len = remaining
                        best_i = start
                        best_parts = (start, remaining)

    if best_parts:
        parts = [best_parts]
        return f'1\n{parts[0][0]} {parts[0][1]}\n'
    elif n > 0:
