import itertools

def compute_score(combo, n):
    # Sum of squared Euclidean distances between all pairs
    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            dx = combo[i][0] - combo[j][0]
            dy = combo[i][1] - combo[j][1]
            total += dx * dx + dy * dy
    return total

def solution(input_str):
