    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x * x + y * y <= r * r:
                points.append((x, y))

    best_score = -1
    best_combo = None

    for combo in itertools.combinations(points, n):
        score = compute_score(combo, n)
        if score > best_score:
            best_score = score
            best_combo = combo

    lines = [str(best_score)]
    for x, y in best_combo:
        lines.append(f"{x} {y}")
    return "\n".join(lines)
