        for i in range(n):
            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        ops = lines[idx]
        idx += 1

        # Track state
        h_shift = 0  # columns shifted right
        v_shift = 0  # rows shifted down
        row_inv = False
        col_inv = False

        for op in ops:
            if op == 'R':
                h_shift = (h_shift + 1) % n
            elif op == 'L':
                h_shift = (h_shift - 1) % n
            elif op == 'D':
                v_shift = (v_shift + 1) % n
            elif op == 'U':
                v_shift = (v_shift - 1) % n
            elif op == 'I':
                row_inv = not row_inv
            elif op == 'C':
                col_inv = not col_inv

        # Build result matrix
        result = [[0] * n for _ in range(n)]

        # Apply inverse transformations
        for i in range(n):
            for j in range(n):
                # Original position after considering shifts
                orig_i = (i - v_shift) % n
                orig_j = (j - h_shift) % n

                # Get the element at original position
                val = matrix[orig_i][orig_j]

                # Apply value transformations if needed
                if row_inv:
                    # Invert based on row values
                    row_p = matrix[orig_i]
                    for k in range(n):
                        if row_p[k] == val:
                            val = k + 1
                            break
                if col_inv:
                    # Invert based on column values
                    col_p = [matrix[k][orig_j] for k in range(n)]
                    for k in range(n):
                        if col_p[k] == val:
                            val = k + 1
                            break

                result[i][j] = val

        results.append('\n'.join(' '.join(map(str, row)) for row in result))

    return '\n\n'.join(results)
