    last = arr[-1]

    def prime_factors(x):
        res = []
        if x % 2 == 0:
            res.append(2)
            while x % 2 == 0:
                x //= 2
        for i in range(3, int(x**0.5) + 1, 2):
            if x % i == 0:
                res.append(i)
                while x % i == 0:
                    x //= i
        if x > 1:
            res.append(x)
        return res

