def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''
    T = int(lines[0])
    results = []

    for i in range(1, T + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if not parts:
            break
        N = int(parts[0])
        K = int(parts[1])

        if K == 0:
            results.append(' '.join(map(str, range(1, N + 1))))
            continue

        # For small N values, check feasibility carefully
        # Position i (1-indexed) can have soldier j (1-indexed) if |i - j| >= K
        # We need to check if a valid perfect matching exists
        if N <= K:
            # Check if we can form valid assignments
            # Specifically, position 1 can only take soldiers >= 1+K
            if 1 + K > N:
                results.append('-1')
                continue

        # Try lexicographically smallest assignment with greedy validation
        # Use backtracking for small N to verify and construct
        perm = [-1] * N
        available = set(range(1, N + 1))

        def is_valid(pos, soldier):
            return abs(soldier - (pos + 1)) >= K

        def can_complete(pos):
            # Check if remaining positions can be assigned from remaining soldiers
            remaining_pos = N - pos
            remaining_soldiers = len(available)
            if remaining_soldiers < remaining_pos:
                return False
            return True

        def backtrack(pos):
            if pos == N:
                return True

            # Try smallest available soldier first for lexicographically smallest result
            for soldier in sorted(available):
                if is_valid(pos, soldier):
                    perm[pos] = soldier
                    available.remove(soldier)
                    if backtrack(pos + 1):
                        return True
                    available.add(soldier)
                    perm[pos] = -1

            return False

        if backtrack(0):
            results.append(' '.join(map(str, perm)))
        else:
            results.append('-1')

    return '\n'.join(results)
