def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return "0"
    n, k = map(int, lines[0].split())
    phones = []
    for line in lines[1:]:
        parts = line.split()
        phone_str, m = parts[0], int(parts[1])
        phones.append((phone_str, m))

    prefix_counts = {}
    for phone_str, m in phones:
        for i in range(len(phone_str)):
            prefix = phone_str[:i+1]
            prefix_counts[prefix] = prefix_counts.get(prefix, 0) + m

    benefits = []
    for prefix, count in prefix_counts.items():
        benefit = len(prefix) * count
        benefits.append(benefit)

    benefits.sort(reverse=True)
    total_benefit = sum(benefits[:k]) if k > 0 else 0

    original_cost = sum(len(phone) * m for phone, m in phones)

    return str(original_cost - total_benefit)
